node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// List tables
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name).join(', '));

// Find order with D7E869
const orders = db.prepare(\"SELECT * FROM orders WHERE order_id LIKE '%D7E869%'\").all();
console.log('\n=== ORDER ===');
console.log(JSON.stringify(orders, null, 2));
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get order items for ORD-D7E869
const items = db.prepare(\"SELECT * FROM order_items WHERE order_id = 'ORD-D7E869'\").all();
console.log('=== ORDER ITEMS ===');
console.log(JSON.stringify(items, null, 2));

// Get product details for each item
for (const item of items) {
    const product = db.prepare(\"SELECT * FROM products WHERE product_id = ?\").get(item.product_id);
    console.log('\n=== PRODUCT: ' + item.product_id + ' ===');
    console.log(JSON.stringify(product, null, 2));

    // Check rt_variants for this product
    const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = ?\").all(item.product_id);
    if (variants.length > 0) {
        console.log('Variants:', JSON.stringify(variants, null, 2));
    }
}

// Also get user details
const user = db.prepare(\"SELECT * FROM users WHERE user_id = 'user_d3d5d0c8'\").get();
console.log('\n=== USER ===');
console.log(JSON.stringify(user, null, 2));
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get payment history for the order
const payments = db.prepare(\"SELECT * FROM order_payments WHERE order_id = 'ORD-D7E869'\").all();
console.log('=== PAYMENT HISTORY ===');
console.log(JSON.stringify(payments, null, 2));

// Get user payment methods
const user = db.prepare(\"SELECT payment_methods_json FROM users WHERE user_id = 'user_d3d5d0c8'\").get();
console.log('\n=== USER PAYMENT METHODS ===');
console.log(user.payment_methods_json);

// Get order details again for status & payment info
const order = db.prepare(\"SELECT order_id, status, payment_method, payment_details_json, total_paid, is_gift, gift_sender, shipping_cost, discount_amount FROM orders WHERE order_id = 'ORD-D7E869'\").get();
console.log('\n=== ORDER PAYMENT SUMMARY ===');
console.log(JSON.stringify(order, null, 2));
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Update order status to cancelled
db.prepare(\"UPDATE orders SET status = 'cancelled', cancel_reason = 'no longer needed' WHERE order_id = 'ORD-D7E869'\").run();

// Update item statuses
db.prepare(\"UPDATE order_items SET item_status = 'cancelled' WHERE order_id = 'ORD-D7E869'\").run();

// Verify the update
const order = db.prepare(\"SELECT order_id, status, cancel_reason, total_paid, payment_method FROM orders WHERE order_id = 'ORD-D7E869'\").get();
console.log('=== UPDATED ORDER ===');
console.log(JSON.stringify(order, null, 2));

const items = db.prepare(\"SELECT oi_id, name, unit_price, item_status FROM order_items WHERE order_id = 'ORD-D7E869'\").all();
console.log('\n=== UPDATED ITEMS ===');
console.log(JSON.stringify(items, null, 2));
"

